npm run chat:probe -- --agent croupier --model claude-haiku-5-5 --say "Let's play Spanish 21." --expect-turn CardTable --click 100 --click Stand --click "Deal again" --expect-turn CardTable --click 100 --say "Late surrender." --click "Deal again" --expect-turn CardTable --click 50 --say Hit. --say Stand. --expect-component CardTable --out .sdlc/evals/rounds/2026-10-14-r1-croupier/runs/spanish-21-haiku-1 --name spanish-21-haiku-1
